#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Standalone PowerPoint Citation Processor

This script processes PowerPoint files to replace citation markers (like 【1†L5-L10】)
with hyperlinks.

Usage:
    python standalone_powerpoint_processor.py input_file.pptx [output_file.pptx]

Dependencies:
    pip install python-pptx
"""

import argparse
import io
import json
import re
import sys
from pathlib import Path
from typing import Protocol, TypeGuard, cast
from urllib.parse import urlparse
import traceback
from pptx import Presentation
from pptx.shapes.base import BaseShape
from pptx.slide import NotesSlide, Slide
from pptx.text.text import TextFrame


# Citation regex pattern - matches patterns like 【1†L5-L10】
BASE_CITE_REGEX = r"【.*?】"


class HasTextFrame(Protocol):
    """Protocol for shapes that have text frames."""

    text_frame: TextFrame


SlideLike = Slide | NotesSlide


def check_has_text_frame(shape: BaseShape) -> TypeGuard[HasTextFrame]:
    """Check if a shape has a text frame."""
    return shape.has_text_frame


def get_hostname(url: str) -> str | None:
    """
    Extracts the hostname from a given URL string.
    Returns None if the URL is malformed or has no hostname.
    """
    try:
        parsed = urlparse(url)
        return parsed.hostname  # e.g. "www.example.com"
    except ValueError:
        return None


def extract_text_from_slide(slide: SlideLike) -> str:
    """Extract all text content from a slide."""
    text = ""
    for shape in slide.shapes:
        if not check_has_text_frame(shape):
            continue
        text_frame = cast(HasTextFrame, shape).text_frame
        text += text_frame.text
    return text


def extract_link_text_from_slide(slide: SlideLike) -> str:
    """Extract hyperlink addresses from a slide."""
    text = ""
    for shape in slide.shapes:
        if not check_has_text_frame(shape):
            continue

        text_frame = shape.text_frame
        for paragraph in text_frame.paragraphs:
            for run in list(paragraph.runs):
                if run.hyperlink.address:
                    text += run.hyperlink.address + " "

    return text.strip()


def has_citations(text: str) -> bool:
    """Check if text contains any citation markers."""
    result = re.search(BASE_CITE_REGEX, text) is not None
    print(f"Checking for citations in text (length: {len(text)}): {result}")
    if result:
        citations = re.findall(BASE_CITE_REGEX, text)
        print(f"Found citations: {citations}")
    return result


def replace_citations_in_slide(
    slide: SlideLike,
    citation_mapping: dict[str, str] | None,
) -> None:
    """
    Replace citation markers in a slide with hyperlinks.

    Args:
        slide: The slide to process
        citation_mapping: Dictionary mapping citation markers to URLs
    """
    for shape in slide.shapes:
        if not check_has_text_frame(shape):
            continue

        text_frame = shape.text_frame
        if citation_mapping is None:
            citation_mapping = {}

        # Step 1: Replace citation markers in text with hyperlinks
        for paragraph in text_frame.paragraphs:
            for run in list(paragraph.runs):
                while True:
                    print("Checking for citation markers in run:", run.text)
                    match = re.search(BASE_CITE_REGEX, run.text)
                    if not match:
                        print("No more citation markers in this run.")
                        break
                    citation_marker = match.group(0)
                    if citation_marker not in citation_mapping:
                        # Remove unknown citation markers
                        print("Removing unknown citation marker:", citation_marker)
                        run.text = run.text.replace(citation_marker, "", 1)
                        continue

                    url = citation_mapping[citation_marker]
                    hostname = get_hostname(url)

                    if not hostname:
                        # Remove citations with invalid URLs
                        run.text = run.text.replace(citation_marker, "", 1)
                        continue

                    start_ix, end_ix = match.span()
                    before = run.text[:start_ix]
                    after = run.text[end_ix:]
                    run.text = before

                    # Create hyperlink run
                    link_run = paragraph.add_run()
                    link_run.text = f"({hostname})"
                    link_run.font.underline = True
                    link_run.font.size = run.font.size
                    link_run.font.color.theme_color = 10  # accent color
                    link_run.hyperlink.address = url

                    # Move link run to correct position
                    run._r.addnext(link_run._r)

                    # Create run for text after citation
                    tail_run = paragraph.add_run()
                    tail_run.text = after
                    link_run._r.addnext(tail_run._r)

                    # Continue processing the tail run
                    run = tail_run

        # Step 2: Update existing hyperlinks that contain citation markers
        for paragraph in text_frame.paragraphs:
            for run in list(paragraph.runs):
                hyperlink_address = run.hyperlink.address
                print("Checking hyperlink address:", hyperlink_address)
                if not hyperlink_address:
                    continue

                match = re.search(BASE_CITE_REGEX, hyperlink_address)
                if not match:
                    continue

                citation_marker = match.group(0)
                if citation_marker in citation_mapping:
                    url = citation_mapping[citation_marker]
                    run.hyperlink.address = url
                else:
                    # Clear invalid citation hyperlink and text
                    run.hyperlink.address = ""
                    run.text = ""


def process_slide_citations(
    slide: SlideLike,
    citation_mapping: dict[str, str] | None,
) -> None:
    """
    Process a single slide to replace citations with hyperlinks.

    Args:
        slide: The slide to process
        citation_mapping: Dictionary mapping citation markers to URLs
    """
    # Extract all text from the slide
    slide_text = extract_text_from_slide(slide)
    link_text = extract_link_text_from_slide(slide)
    all_text = slide_text + "\n\n" + link_text

    # Only process slides that contain citations
    if not has_citations(all_text):
        return

    # Replace citations with hyperlinks
    replace_citations_in_slide(slide, citation_mapping)


